/* VisionON role-based safety portal. Data is served by the authenticated API. */
const roles={employee:{name:'Jordan Miller',initials:'JM',title:'Employee',site:'North Plant'},safety:{name:'Jordan Miller',initials:'JM',title:'Safety Manager',site:'North Plant'},admin:{name:'Alex Chen',initials:'AC',title:'Platform Admin',site:'All sites'},hq:{name:'Morgan Reed',initials:'MR',title:'VP · Operations',site:'Executive view'}};
let activeRole='safety',activePage='Overview',incidentFilter='All',searchText='',signedIn=false,needsPasswordChange=false,ssoEnabled=false,currentUser=null,liveData=false,apiSites=[],apiIncidents=[],apiReports=[],apiTasks=[],apiCameras=[],apiEmployees=[],apiDashboard={};
const sampleIncidents=[
 {id:'INC-2841',time:'10:42 AM',site:'North Plant',camera:'Line 04 · East',person:'Jordan Miller',event:'Hard hat missing',severity:'High',state:'Review'},
 {id:'INC-2840',time:'10:18 AM',site:'North Plant',camera:'Dock 02 · North',person:'R. Singh',event:'Safety vest missing',severity:'Medium',state:'Pending'},
 {id:'INC-2839',time:'09:56 AM',site:'North Plant',camera:'Line 01 · West',person:'Unidentified',event:'Restricted zone entry',severity:'Critical',state:'Review'},
 {id:'INC-2838',time:'09:21 AM',site:'North Plant',camera:'Warehouse · 03',person:'A. Foster',event:'Safety glasses missing',severity:'Low',state:'Posted'},
 {id:'INC-2837',time:'08:47 AM',site:'North Plant',camera:'Line 04 · East',person:'J. Miller',event:'Safety vest missing',severity:'Medium',state:'Resolved'}
];
let incidents=sampleIncidents;
const pages={Profile:'Profile',Overview:'Overview',Incidents:'Incident log','Live cameras':'Live cameras',Analytics:'Analytics','My safety':'My safety',Tasks:'Tasks','Safety reports':'Safety reports','Access control':'Access control',Audit:'Audit','HQ briefings':'HQ briefings','Incident reviews':'Incident reviews'};
const employeeNav=[['My safety','S'],['Tasks','T'],['Profile','P']];const safetyNav=[['Overview','O'],['Incidents','I'],['Live cameras','C'],['Analytics','A'],['Safety reports','R'],['Profile','P']];const adminNav=[['Access control','A'],['Audit','L'],['Profile','P']];const hqNav=[['Overview','O'],['HQ briefings','B'],['Incident reviews','I'],['Profile','P']];
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function initials(name){return name.split(/\s+/).map(w=>w[0]).join('').slice(0,2).toUpperCase()}
function navForRole(){return {employee:employeeNav,safety:safetyNav,admin:adminNav,hq:hqNav}[activeRole]}
function allowedPages(){return new Set(navForRole().map(x=>x[0]))}
function setRole(role){if(!signedIn)return;activeRole=role;activePage=navForRole()[0][0];render()}
function setPage(page){if(!allowedPages().has(page))return;activePage=page;render();document.querySelector('.sidebar').classList.remove('open');if(liveData)loadLiveData().then(()=>render()).catch(err=>toast(err.message))}
function renderNav(){document.getElementById('navigation').innerHTML=navForRole().map(([name,icon])=>`<button class="nav-item ${activePage===name?'active':''}" data-page="${esc(name)}"><span class="nav-icon">${icon}</span>${esc(name)}${name==='Incidents'?'<span class="nav-count">12</span>':''}</button>`).join('')}
function renderHeader(){const r=roles[activeRole];for(const [id,value] of Object.entries({avatar:r.initials,userName:r.name,userRole:r.title,topAvatar:r.initials,topName:r.name,topRole:r.title,topSite:liveData?(apiSites[0]?.name||'No site access'):r.site,crumb:activePage}))document.getElementById(id).textContent=value;document.getElementById('profileButton').classList.add('hidden');document.getElementById('topRoleButton').classList.add('hidden');document.getElementById('logoutButton').classList.remove('hidden');document.title=`${activePage} · VisionON`;document.getElementById('navigation').addEventListener('click',e=>{const btn=e.target.closest('[data-page]');if(btn)setPage(btn.dataset.page)})}
function heading(title,sub,action='',eyebrow='SAFETY INTELLIGENCE'){return `<div class="page-heading"><div><div class="section-eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div><div class="heading-actions">${action}<span class="date-label">10 OCT 2026 &nbsp;↗</span></div></div>`}
function metric(label,value,change,foot,symbol,cls=''){return `<div class="metric-card"><div class="metric-top">${label}<span class="metric-symbol">${symbol}</span></div><div class="metric-number">${value}</div><div class="metric-bottom"><span class="metric-change ${cls}">${change}</span>${foot}</div></div>`}
function chartPanel(){if(liveData)return `<section class="panel"><div class="panel-heading"><div><div class="panel-title">Safety event trends</div><div class="panel-subtitle">Live database records · trend series will appear as events accrue</div></div></div><div class="chart-wrap" style="display:grid;place-items:center;color:var(--muted);font-size:10px">${apiIncidents.length?`${apiIncidents.length} scoped incident records loaded`:'No incident records in this scope yet.'}</div></section>`;return `<section class="panel"><div class="panel-heading"><div><div class="panel-title">Safety events over time</div><div class="panel-subtitle">Incident volume by day · last 7 days</div></div><select class="select-input" id="chartPeriod" aria-label="Chart period"><option>Last 7 days</option><option>Last 30 days</option></select></div><div class="chart-legend"><span><i class="legend-dot" style="background:var(--lime)"></i>PPE violations</span><span><i class="legend-dot" style="background:#7eb8e8"></i>Near misses</span></div><div class="chart-wrap"><svg class="chart-svg" viewBox="0 0 610 180" preserveAspectRatio="none" aria-label="Line chart showing safety events across seven days"><defs><linearGradient id="greenFill" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#d7ff70" stop-opacity=".16"/><stop offset="1" stop-color="#d7ff70" stop-opacity="0"/></linearGradient></defs><g class="chart-grid"><path d="M36 20H600M36 57H600M36 94H600M36 131H600"/></g><g class="chart-label"><text x="3" y="23">24</text><text x="3" y="60">16</text><text x="10" y="97">8</text><text x="17" y="134">0</text><text x="34" y="157">MON</text><text x="126" y="157">TUE</text><text x="220" y="157">WED</text><text x="315" y="157">THU</text><text x="408" y="157">FRI</text><text x="500" y="157">SAT</text><text x="575" y="157">SUN</text></g><path class="chart-area" d="M38 86 C75 72 85 101 128 66 S174 84 221 48 S267 67 314 81 S363 98 407 54 S460 78 502 34 S552 61 598 27 L598 132 L38 132Z"/><path class="chart-line1" d="M38 86 C75 72 85 101 128 66 S174 84 221 48 S267 67 314 81 S363 98 407 54 S460 78 502 34 S552 61 598 27"/><path class="chart-line2" d="M38 111 C81 103 85 112 128 93 S178 110 221 87 S272 105 314 99 S366 113 407 91 S461 108 502 84 S556 100 598 75"/><circle class="chart-point" cx="598" cy="27" r="4"/></svg></div></section>`}
function sitePanel(){const rows=liveData?apiSites.map(s=>{const siteIncidents=apiIncidents.filter(i=>i.site===s.name);const cams=apiCameras.filter(c=>c.site_name===s.name);return[s.name,`${cams.length} cameras · ${siteIncidents.length} incidents`,cams.length?`${cams.filter(c=>c.health==='operational').length}/${cams.length} online`:'—',''] }):[['North Plant','12 active cameras','96'],['South Warehouse','8 active cameras','91'],['East Distribution','6 active cameras','88'],['West Assembly','9 active cameras','84']];return `<section class="panel"><div class="panel-heading"><div><div class="panel-title">${liveData?'Site operations':'Site safety score'}</div><div class="panel-subtitle">${liveData?'Assigned site data · compliance score not configured':'Current compliance by location'}</div></div><button class="text-link" data-goto="Analytics">All sites ↗</button></div><div class="site-list">${rows.map((s,i)=>`<div class="site-row"><div><div class="site-name">${esc(s[0])}</div><div class="site-meta">${esc(s[1])}</div></div><div class="site-status ${liveData?'':' '+(i===3?'warn':'')}">${liveData?'● Database connected':i===3?'● Review needed':'● Operational'}</div><div class="site-score">${s[2]}${liveData?'':`<div class="score-bar"><i style="width:${s[2]}%"></i></div>`}</div></div>`).join('')||'<div class="table-empty">No site records are available for this account.</div>'}</div></section>`}
function filteredIncidents(){return incidents.filter(i=>{const roleMatch=activeRole==='employee'?(!liveData||i.person===roles.employee.name):true;const filterMatch=incidentFilter==='All'||i.state===incidentFilter;const text=`${i.id} ${i.site} ${i.camera} ${i.person} ${i.event}`.toLowerCase().includes(searchText.toLowerCase());return roleMatch&&filterMatch&&text})}
function incidentRows(list){if(!list.length)return `<tr><td colspan="8" class="table-empty">No incidents match this view.</td></tr>`;return list.map(i=>`<tr class="clickable" data-incident="${i.id}"><td class="id-cell">${i.id}</td><td class="incident-time">${i.time}</td><td>${i.camera}</td><td>${esc(i.person)}</td><td>${i.event}</td><td><span class="tag ${i.severity.toLowerCase()}"><i></i>${i.severity}</span></td><td><span class="tag ${i.state.toLowerCase()}">${i.state}</span></td><td><button class="text-link" data-incident="${i.id}">Open ↗</button></td></tr>`).join('')}
function tablePanel(opts={}){const employee=activeRole==='employee';const cols=employee?'<th>REFERENCE</th><th>DETECTED</th><th>CAMERA</th><th>EVENT</th><th>STATUS</th><th></th>':'<th>REFERENCE</th><th>TIME</th><th>CAMERA</th><th>PERSON</th><th>DETECTION</th><th>LEVEL</th><th>STATUS</th><th></th>';const rows=incidentRows(filteredIncidents());return `<section class="panel"><div class="panel-heading"><div><div class="panel-title">${opts.title|| (employee?'Your recent observations':'Recent incidents')}</div><div class="panel-subtitle">${employee?'Events associated with your account':'AI-detected and manager-submitted safety events'}</div></div><button class="text-link" data-goto="${employee?'My safety':'Incidents'}">${opts.link||'View log ↗'}</button></div><div class="table-toolbar"><div class="section-eyebrow">${employee?'PERSONAL RECORD':'LIVE INCIDENT FEED'}</div>${opts.search?'<input class="search-input" id="incidentSearch" placeholder="⌕  Search incidents" aria-label="Search incidents">':''}</div><div class="table-wrap"><table><thead><tr>${cols}</tr></thead><tbody>${rows}</tbody></table></div></section>`}
function timelinePanel(){if(liveData)return `<section class="panel"><div class="panel-heading"><div><div class="panel-title">Recent safety records</div><div class="panel-subtitle">Loaded from your authorized data scope</div></div></div><div class="timeline-list">${apiIncidents.slice(0,3).map(i=>`<div class="timeline-item"><span class="timeline-icon">◉</span><div class="timeline-copy"><strong>${esc(i.id)}</strong> · ${esc(i.event)}<span>${esc(i.site)} · ${esc(i.time||'Recorded')}</span></div></div>`).join('')||'<div class="table-empty">No recent records.</div>'}</div></section>`;return `<section class="panel"><div class="panel-heading"><div><div class="panel-title">Activity</div><div class="panel-subtitle">Latest updates across your sites</div></div><button class="text-link" data-goto="Audit">Full audit ↗</button></div><div class="timeline-list"><div class="timeline-item"><span class="timeline-icon">↗</span><div class="timeline-copy"><strong>INC-2838 shared with HQ</strong> · safety report published<span>10:04 AM · Morgan Reed notified</span></div></div><div class="timeline-item"><span class="timeline-icon">✓</span><div class="timeline-copy"><strong>Corrective action completed</strong> · West Assembly<span>9:32 AM · PPE refresher acknowledged</span></div></div><div class="timeline-item"><span class="timeline-icon">◉</span><div class="timeline-copy"><strong>Camera 04 is operational</strong> · North Plant<span>8:16 AM · signal restored</span></div></div></div></section>`}
function privacy(text){return `<div class="privacy-note"><span class="lock">⌑</span><span>${text}</span></div>`}
function overview(){if(activeRole==='employee')return employeeSafety();if(activeRole==='hq')return hqOverview();const d=apiDashboard;return `${heading(`Good morning, ${liveData?esc(currentUser?.name||'there'):'Jordan'}`,'Here is your operational safety snapshot.',`<button class="button-primary" data-action="new-report"><span class="plus">+</span> New safety report</button>`)}<div class="metric-grid">${metric('ACTIVE INCIDENTS',liveData?d.active_incidents||0:'12',liveData?'LIVE':'↑ 2',liveData?'scoped database records':'vs. previous week','◷','warn')}${metric('PPE COMPLIANCE',liveData?'—':'96.4%',liveData?'Not configured':'↑ 1.8%',liveData?'model feed not connected':'across all monitored sites','◉')}${metric('CAMERAS ONLINE',liveData?`${d.cameras_online||0} / ${d.cameras_total||0}`:'35 / 36',liveData?'LIVE':'97.2%',liveData?'assigned site cameras':'system availability','⌕')}${metric('REPORTS TO HQ',liveData?apiReports.filter(r=>r.status!=='published').length:'03',liveData?'DATABASE':'↑ 1',liveData?'manager reports':'awaiting executive review','↗','warn')}</div><div class="overview-grid">${chartPanel()}${sitePanel()}</div><div class="overview-grid lower-grid">${tablePanel({title:'Recent incidents',search:true})}${timelinePanel()}</div>`}
function dashboard(){const d=apiDashboard;return `<div class="metric-grid">${metric('ACTIVE INCIDENTS',liveData?d.active_incidents||0:'12',liveData?'LIVE':'↑ 2',liveData?'scoped database records':'vs. previous week','◷','warn')}${metric('PPE COMPLIANCE',liveData?'—':'96.4%',liveData?'Not configured':'↑ 1.8%',liveData?'model feed not connected':'across monitored sites','◉')}${metric('CAMERAS ONLINE',liveData?`${d.cameras_online||0} / ${d.cameras_total||0}`:'35 / 36',liveData?'LIVE':'97.2%',liveData?'assigned site cameras':'system availability','⌕')}${metric('REPORTS TO HQ',liveData?apiReports.length:'03',liveData?'DATABASE':'↑ 1',liveData?'published reports':'awaiting executive review','↗','warn')}</div><div class="overview-grid">${chartPanel()}${sitePanel()}</div>`}
function employeeSafety(){const mine=filteredIncidents();return `${heading('My safety','Your personal safety tasks and verified observations.', '', 'EMPLOYEE PORTAL')}${privacy('<strong>Private to you and your designated safety team.</strong> You can only see tasks and verified incidents associated with your account.') }<div class="metric-grid">${metric('OPEN TASKS','02','1 due soon','complete before shift end','✓','warn')}${metric('MY OBSERVATIONS',String(mine.length).padStart(2,'0'),'This month','incidents linked to you','◷')}${metric('PPE STATUS','Compliant','● Verified','latest camera check · 10:42 AM','◉')}</div><div class="task-grid"><section class="panel"><div class="panel-heading"><div><div class="panel-title">Your open tasks</div><div class="panel-subtitle">Required actions assigned to you</div></div><button class="text-link" data-goto="Tasks">All tasks ↗</button></div><div class="task-list"><div class="task-item"><div class="task-icon">✓</div><div class="task-detail"><strong>Review hard hat observation</strong><span>North Plant · Line 04 East · INC-2841</span></div><div class="task-aside"><small>DUE TODAY</small><strong>3:00 PM</strong></div></div><div class="task-item"><div class="task-icon">▤</div><div class="task-detail"><strong>Complete PPE refresher</strong><span>Safety training · 5 minute module</span></div><div class="task-aside"><small>DUE OCT 12</small><strong>In 2 days</strong></div></div></div></section><section class="panel"><div class="panel-title">Shift safety status</div><div class="panel-subtitle">Today · North Plant</div><div style="margin:19px 0 14px;font:500 25px 'DM Mono',monospace;color:var(--lime)">COMPLIANT</div><div class="ppe-status"><span class="secure-dot"></span> PPE detected · camera 04</div><div class="site-meta" style="margin-top:12px;line-height:1.6">Last check at 10:42 AM. Your manager is notified only if action is needed.</div></section></div><div style="height:13px"></div>${tablePanel({title:'Observations linked to you',link:'All observations'})}`}
function incidentsPage(){return `${heading('Incident log','Review AI detections and safety events from your designated sites.',`<button class="button-primary" data-action="new-report"><span class="plus">+</span> New safety report</button>`)}${privacy('<strong>Restricted site scope.</strong> You can review incidents for North Plant only. Individual identity is shown to authorized safety staff for follow-up; reports shared with HQ use incident details without employee identifiers.') }<div class="filter-row">${['All','Review','Pending','Posted','Resolved'].map(x=>`<button class="pill-filter ${incidentFilter===x?'active':''}" data-filter="${x}">${x}</button>`).join('')}</div>${tablePanel({title:'Incidents · North Plant',search:true,link:'Export report ↗'})}`}
function analytics(){return `${heading('Safety analytics','Cross-site safety trends and operational indicators for your assigned sites.','','SAFETY INTELLIGENCE · NORTH PLANT')}${dashboard()}<div class="lower-grid">${sitePanel()}${timelinePanel()}</div>`}
function cameraPage(){return `${heading('Live cameras','Health and safety signals for cameras at North Plant.','','NORTH PLANT · CAMERA NETWORK')}${privacy('<strong>Camera access is permission controlled.</strong> This prototype shows camera health only. Live video requires a separately authorized secure stream and retention policy.') }<div class="metric-grid">${metric('CAMERAS ONLINE','11 / 12','● Stable','one camera needs attention','◉')}${metric('AI DETECTION','Active','● Running','PPE model · site deployment','⌁')}${metric('LAST SYNC','12 sec','● Current','site events pipeline','↗')}</div><div class="panel"><div class="panel-heading"><div><div class="panel-title">Camera network</div><div class="panel-subtitle">Live status · North Plant</div></div><button class="button-secondary" data-toast="Camera configuration is managed by your site administrator.">Manage cameras</button></div><div class="site-list">${[['Line 04 · East','Camera NV-04 · PPE zones 2','Operational','PPE: hard hat, vest'],['Dock 02 · North','Camera NV-12 · entry monitoring','Operational','Entry: restricted zone'],['Line 01 · West','Camera NV-01 · PPE zones 1','Operational','PPE: hard hat, eyewear'],['Warehouse · 03','Camera NV-18 · aisle monitoring','Signal unstable','Reconnecting · since 10:21 AM']].map((x,i)=>`<div class="site-row"><div><div class="site-name">${x[0]}</div><div class="site-meta">${x[1]}</div></div><div class="site-status ${i===3?'warn':''}">● ${x[2]}</div><div class="site-score" style="width:150px">${x[3]}</div></div>`).join('')}</div></div>`}
function tasksPage(){const action=activeRole==='safety'?'<button class="button-primary" data-action="assign-task"><span class="plus">+</span> Assign task</button>':'';return `${heading(activeRole==='employee'?'My tasks':'Safety tasks','Assigned actions, due dates, and completion status.',action,'PERSONAL ACTIONS')}${activeRole==='employee'?privacy('<strong>Visible only to you and your safety team.</strong> Completing an action records an acknowledgement in the site audit log.'):''}<div class="panel"><div class="panel-title">Open actions</div><div class="task-list"><div class="task-item"><div class="task-icon">✓</div><div class="task-detail"><strong>Review hard hat observation</strong><span>North Plant · Line 04 East · INC-2841</span></div><div class="task-aside"><small>DUE TODAY</small><strong>3:00 PM</strong></div><button class="button-secondary" data-action="complete-task">Mark complete</button></div><div class="task-item"><div class="task-icon">▤</div><div class="task-detail"><strong>Complete PPE refresher</strong><span>Safety training · 5 minute module</span></div><div class="task-aside"><small>DUE OCT 12</small><strong>In 2 days</strong></div><button class="button-secondary" data-action="complete-task">Start</button></div></div></div><div style="height:14px"></div>${tablePanel({title:'Related safety observations'})}`}
function reportPage(){return `${heading('Safety reports','Document an incident, action, or improvement suggestion for your site.',`<button class="button-primary" data-action="new-report"><span class="plus">+</span> New safety report</button>`)}${privacy('<strong>Reports shared to HQ are privacy screened.</strong> Employee names and personal identifiers are excluded from executive summaries unless an approved safety escalation requires them.') }<div class="report-flow"><div class="flow-step"><span class="flow-number">01 — CAPTURE</span><strong>Record the event</strong><span>Describe what happened or share an improvement suggestion.</span></div><div class="flow-step"><span class="flow-number">02 — REVIEW</span><strong>Safety manager review</strong><span>Validate details, assign corrective actions, and add context.</span></div><div class="flow-step"><span class="flow-number">03 — SHARE</span><strong>Publish to VP / HQ</strong><span>Send a privacy-screened summary to the executive portal.</span></div></div><div class="panel"><div class="panel-title">Recent reports</div><div class="event-log"><div class="event-row"><strong>Improve marking around Line 04 walkway</strong><span>Suggestion · North Plant · Shared with HQ · INC-2838</span></div><div class="event-row"><strong>Warehouse eyewear signage refresh</strong><span>Corrective action · North Plant · In manager review</span></div><div class="event-row"><strong>Dock 02 pedestrian / forklift near miss</strong><span>Incident · North Plant · Shared with HQ · INC-2829</span></div></div></div>`}
function accessPage(){return `${heading('Access control','Manage roles, site grants, and least-privilege access.','','PLATFORM ADMINISTRATION')}${privacy('<strong>Content blind by design.</strong> Admins can manage identities, roles, site scope, and access logs. Incident narratives, video, and confidential reports are withheld from this portal.') }<div class="audit-banner"><strong>ADMIN VIEW · METADATA ONLY</strong> &nbsp; Sensitive safety reports and personal incident details are not available in this workspace.</div><div class="access-grid"><section class="panel"><div class="panel-heading"><div><div class="panel-title">People & permissions</div><div class="panel-subtitle">Role assignments and site scope · 8 users</div></div><button class="button-primary" data-action="invite">+ Invite user</button></div>${[['Jordan Miller','j.miller@visionon.example','Safety Manager','North Plant'],['Priya Nair','p.nair@visionon.example','Safety Manager','South Warehouse'],['Morgan Reed','m.reed@visionon.example','VP / HQ','All sites · summaries'],['Taylor Brooks','t.brooks@visionon.example','Employee','North Plant'],['Alex Chen','a.chen@visionon.example','Platform Admin','Access metadata only'],['Sam Rivera','s.rivera@visionon.example','Employee','North Plant']].map((u,i)=>`<div class="access-row"><div><strong>${u[0]}</strong><small>${u[1]}</small></div><span class="role-chip">${u[2]}</span><span class="scope-mask ${i===4?'restricted':''}">${u[3]}</span><button class="text-link" data-action="edit-access" data-name="${u[0]}">Edit</button></div>`).join('')}</section><section class="panel"><div class="panel-title">Role boundaries</div><div class="event-log"><div class="event-row"><strong>Employee</strong><span>Own tasks and verified linked incidents only</span></div><div class="event-row"><strong>Safety manager</strong><span>Assigned sites, cameras, analytics, report publishing</span></div><div class="event-row"><strong>VP / HQ</strong><span>Published incident summaries and recommendations</span></div><div class="event-row"><strong>Platform admin</strong><span>Account, role, site grants, audit metadata only</span></div></div><button class="button-secondary" style="margin-top:13px" data-goto="Audit">View access audit ↗</button></section></div>`}
function auditPage(){return `${heading('Access audit','Administrative actions and data-access metadata.','','PLATFORM ADMINISTRATION')}${privacy('<strong>Audit content is metadata only.</strong> This view records changes to grants and sign-in events; it does not reveal incident narratives, camera footage, or private safety reports.') }<div class="metric-grid">${metric('ACTIVE USERS','08','● Current','across all site workspaces','♙')}${metric('PENDING INVITES','02','Awaiting','user acceptance','↗')}${metric('ROLE CHANGES','03','This month','recorded changes','⌁')}</div><section class="panel"><div class="panel-title">Administrative events</div><div class="event-log">${[['10:36 AM','Role grant updated','j.miller@visionon.example · North Plant · Safety Manager'],['09:52 AM','User invitation created','new.user@visionon.example · Employee · North Plant'],['Yesterday, 4:12 PM','Site access revoked','l.park@visionon.example · East Distribution'],['Oct 08, 11:34 AM','Successful sign in','a.chen@visionon.example · Platform Admin']].map(x=>`<div class="event-row"><strong>${x[1]}</strong><span>${x[0]} · ${x[2]}</span></div>`).join('')}</div></section>`}
function hqOverview(){return `${heading('Executive overview','Safety performance and published reports across your organization.','','VP / HQ · EXECUTIVE VIEW')}${privacy('<strong>Executive view is privacy screened.</strong> You can access safety reports published by managers, aggregated site metrics, and recommendations. Direct camera feeds and employee task details are not included.') }<div class="metric-grid">${metric('OPEN REPORTS','03','↑ 1','awaiting executive review','▤','warn')}${metric('ORG COMPLIANCE','94.8%','↑ 2.1%','quarter to date','◉')}${metric('SITES ON TRACK','3 / 4','1 needs focus','weekly safety review','⌁','warn')}${metric('ACTIONS COMPLETED','28','↑ 12%','this month','✓')}</div><div class="overview-grid">${chartPanel()}${sitePanel()}</div><div class="lower-grid">${hqBriefingPanel()}${timelinePanel()}</div>`}
function hqBriefingPanel(){return `<section class="panel"><div class="panel-heading"><div><div class="panel-title">Published safety reports</div><div class="panel-subtitle">Manager-approved · privacy-screened</div></div><button class="text-link" data-goto="HQ briefings">All reports ↗</button></div><div class="event-log"><div class="event-row"><strong>Pedestrian route improvement · North Plant</strong><span>RECOMMENDATION · OCT 10 · 2 actions proposed</span></div><div class="event-row"><strong>Dock near miss · South Warehouse</strong><span>INCIDENT · OCT 09 · Corrective actions assigned</span></div><div class="event-row"><strong>Monthly safety performance · Q4</strong><span>SUMMARY · OCT 07 · 4 sites included</span></div></div></section>`}
function hqReports(){return `${heading('HQ briefings','Manager-reviewed safety reports and recommendations published for executive review.','','VP / HQ · PUBLISHED REPORTS')}${privacy('<strong>Only approved reports appear here.</strong> Summaries omit employee identities and video. You may acknowledge a report or request a follow-up from the site safety lead.') }<div class="filter-row">${['All','Incident','Recommendation','Summary'].map((x,i)=>`<button class="pill-filter ${i===0?'active':''}" data-hq-filter="${x}">${x}</button>`).join('')}</div><div id="hqReportList" class="panel"><div class="panel-title">Published reports · 3</div>${hqBriefingPanel().replace(/<section class="panel">|<\/section>/g,'')}</div>`}
function hqReviews(){const hqItems=incidents.filter(i=>i.state==='Posted');return `${heading('Incident reviews','Privacy-screened incidents and recommendations shared by site safety managers.','','VP / HQ · REVIEW QUEUE')}${privacy('<strong>Incident identities are masked.</strong> Site managers control which validated incidents are published. Review and acknowledge the operational summary below.') }<div class="panel"><div class="panel-heading"><div><div class="panel-title">Published incidents</div><div class="panel-subtitle">${hqItems.length} items shared for executive visibility</div></div><button class="text-link" data-goto="HQ briefings">View briefings ↗</button></div><div class="table-wrap"><table><thead><tr><th>REFERENCE</th><th>SITE</th><th>EVENT</th><th>LEVEL</th><th>STATUS</th><th></th></tr></thead><tbody>${hqItems.map(i=>`<tr><td class="id-cell">${i.id}</td><td>${i.site}</td><td>${i.event}</td><td><span class="tag ${i.severity.toLowerCase()}">${i.severity}</span></td><td><span class="tag posted">Published</span></td><td><button class="text-link" data-incident="${i.id}">Review ↗</button></td></tr>`).join('')}</tbody></table></div></div>`}
function profilePage(){const user=currentUser||{};const role=roles[activeRole];const sites=apiSites.map(s=>s.name);return `${heading('My profile','Your account identity, assigned role, and site access.','','ACCOUNT SETTINGS')}<section class="panel profile-card"><div class="profile-summary"><div class="avatar profile-avatar">${esc(initials(user.name||role.name))}</div><div><h2>${esc(user.name||role.name)}</h2><p>${esc(user.email||'')}</p></div></div><div class="profile-details"><div><span>PORTAL ROLE</span><strong>${esc(role.title)}</strong></div><div><span>ACCOUNT STATUS</span><strong><i class="secure-dot"></i> Active</strong></div><div class="profile-sites"><span>ASSIGNED SITE ACCESS</span><strong>${sites.length?sites.map(esc).join(', '):esc(role.site)}</strong></div></div><div class="profile-actions"><p>Need a role or site change? Contact your VisionON administrator.</p><button class="button-primary" id="profileLogout" type="button">Sign out</button></div></section>`}
function pageContent(){switch(activePage){case'Profile':return profilePage();case'Overview':return overview();case'Incidents':case'My safety':return activeRole==='employee'?employeeSafety():incidentsPage();case'Live cameras':return cameraPage();case'Analytics':return analytics();case'Tasks':return tasksPage();case'Safety reports':return reportPage();case'Access control':return accessPage();case'Audit':return auditPage();case'HQ briefings':return hqReports();case'Incident reviews':return hqReviews();default:return overview()}}
function loginScreen(){return `<main class="login-screen"><section class="login-card"><a class="brand login-brand" href="#login"><span class="brand-mark"><svg viewBox="0 0 32 32" fill="none"><path d="M3 16S7.7 7 16 7s13 9 13 9-4.7 9-13 9S3 16 3 16Z" stroke="currentColor" stroke-width="2.1"/><circle cx="16" cy="16" r="4.2" stroke="currentColor" stroke-width="2.1"/><circle cx="16" cy="16" r="1.6" fill="currentColor"/></svg></span><span>vision<span class="brand-light">on</span><small>SAFETY INTELLIGENCE</small></span></a><div class="login-eyebrow"><i class="secure-dot"></i> SECURE WORKSPACE</div><h1>Welcome back.</h1><p class="login-subtitle">Sign in to your VisionON safety portal.</p><form id="loginForm" class="login-form"><label for="loginEmail">Work email</label><div class="login-input-wrap"><span>✉</span><input id="loginEmail" type="email" autocomplete="username" placeholder="you@company.com" required></div><div class="login-password-label"><label for="loginPassword">Password</label></div><div class="login-input-wrap"><span>⌑</span><input id="loginPassword" type="password" autocomplete="current-password" placeholder="Enter your password" required><button type="button" class="show-password" id="togglePassword">Show</button></div><div class="login-error" id="loginError" role="alert"></div><button class="login-submit" type="submit">Sign in <span>→</span></button></form><div class="login-footer"><span>© 2026 VisionON</span><span>🔒 Encrypted workspace</span></div></section><aside class="login-aside"><div class="login-orbit orbit-one"></div><div class="login-orbit orbit-two"></div><div class="login-aside-content"><div class="login-aside-tag"><i class="secure-dot"></i> SAFETY INTELLIGENCE · LIVE</div><div class="login-visual"><div class="visual-ring ring-one"></div><div class="visual-ring ring-two"></div><div class="visual-eye"><svg viewBox="0 0 80 80" fill="none"><path d="M7 40S18 20 40 20s33 20 33 20-11 20-33 20S7 40 7 40Z" stroke="currentColor" stroke-width="2"/><circle cx="40" cy="40" r="10" stroke="currentColor" stroke-width="2"/><circle cx="40" cy="40" r="3" fill="currentColor"/></svg></div><span class="scan-line"></span><span class="scan-target target-a">PPE · VERIFIED</span><span class="scan-target target-b">NORTH PLANT · ONLINE</span></div><div class="login-aside-copy"><span class="section-eyebrow">SEE SAFETY CLEARLY</span><h2>Every signal.<br>One safer workplace.</h2><p>Bring site teams, safety leaders, and executives together around a clearer view of workplace safety.</p></div><div class="aside-stats"><div><strong>96.4<span>%</span></strong><small>PPE COMPLIANCE</small></div><div><strong>35<span>/36</span></strong><small>CAMERAS ONLINE</small></div><div><strong>04</strong><small>CONNECTED SITES</small></div></div><div class="aside-foot"><span>VISIONON SAFETY PLATFORM</span><span>BUILT FOR PEOPLE FIRST</span></div></div></aside></main>`}
async function apiRequest(url,options={}){const response=await fetch(url,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(options.headers||{})},...options});const payload=response.status===204?{}:await response.json().catch(()=>({}));if(!response.ok)throw new Error(payload.error||`Request failed (${response.status}).`);return payload}
async function loadLiveData(){if(!liveData)return;const requests=[apiRequest('/api/sites'),apiRequest('/api/dashboard')];if(activeRole==='employee'||activeRole==='safety')requests.push(apiRequest('/api/incidents'));if(activeRole==='employee'||activeRole==='safety')requests.push(apiRequest('/api/tasks'));if(activeRole==='safety')requests.push(apiRequest('/api/cameras'),apiRequest('/api/reports'));if(activeRole==='hq')requests.push(apiRequest('/api/reports'));if(activeRole==='admin')requests.push(apiRequest('/api/admin/users'),apiRequest('/api/admin/audit'));const results=await Promise.allSettled(requests);let n=0;const val=()=>{const r=results[n++];if(r.status==='rejected')throw r.reason;return r.value};const sites=val();apiSites=sites.sites||[];try{apiDashboard=val()}catch{apiDashboard={}}if(activeRole==='employee'||activeRole==='safety'){const data=val();const rows=data.incidents||data.reports||[];apiIncidents=rows.map(i=>({id:i.reference||String(i.id),time:i.occurred_at?new Date(i.occurred_at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}):'',site:i.site_name||'',camera:i.camera_label||'—',person:activeRole==='employee'?(currentUser?.name||'You'):(i.person_name||'Privacy screened'),event:i.event_type||i.type||'Published report',severity:String(i.severity||'low').replace(/^./,c=>c.toUpperCase()),state:({pending:'Pending',review:'Review',resolved:'Resolved',false_positive:'Resolved',published:'Posted'})[i.status]||'Review',dbId:i.id}));incidents=apiIncidents;const tasks=val();apiTasks=tasks.tasks||[]}if(activeRole==='safety'){const cameras=val();apiCameras=cameras.cameras||[];const reports=val();apiReports=reports.reports||[];const employees=await apiRequest('/api/site/employees');apiEmployees=employees.employees||[]}if(activeRole==='hq'){const reports=val();apiReports=reports.reports||[];apiIncidents=reports.reports||[]}if(activeRole==='admin'){const users=val();apiUsers=users.users||[];const audit=val();apiAudit=audit.events||[]}}
let apiUsers=[],apiAudit=[];
function syncLiveDom(){if(!liveData)return;const numbers=[...document.querySelectorAll('.metric-number')];let values=[],labels=[];if(activeRole==='employee'){values=[apiTasks.filter(t=>t.status==='open').length,apiIncidents.length,'Not connected'];labels=['OPEN TASKS','MY OBSERVATIONS','PPE STATUS']}else if(activeRole==='safety'){if(activePage==='Live cameras'){values=[`${apiCameras.filter(c=>c.health==='operational').length} / ${apiCameras.length}`,'Not connected','—'];labels=['CAMERAS ONLINE','PPE MODEL','LAST SYNC']}else{values=[apiDashboard.active_incidents||0,'—',`${apiDashboard.cameras_online||0} / ${apiDashboard.cameras_total||0}`,apiReports.filter(r=>r.status!=='published').length];labels=['ACTIVE INCIDENTS','PPE COMPLIANCE','CAMERAS ONLINE','REPORTS TO HQ']}}else if(activeRole==='hq'){values=[apiReports.length,'Not configured',`${apiSites.length} sites`,'—'];labels=['PUBLISHED REPORTS','PPE COMPLIANCE','SITES IN VIEW','ACTIONS COMPLETED']}else{values=[apiUsers.filter(u=>u.active).length,'—','—'];labels=['ACTIVE USERS','PENDING INVITES','ROLE CHANGES']}numbers.forEach((el,i)=>{if(values[i]!==undefined)el.textContent=values[i];const foot=el.parentElement.querySelector('.metric-bottom');if(foot)foot.innerHTML='<span class="metric-change">LIVE</span>authorized records';const title=el.parentElement.querySelector('.metric-top');if(title&&labels[i])title.firstChild.textContent=labels[i]})
 const taskHtml=apiTasks.map(t=>`<div class="task-item"><div class="task-icon">✓</div><div class="task-detail"><strong>${esc(t.title)}</strong><span>${esc(t.site_name||'Assigned task')}${t.reference?' · '+esc(t.reference):''}</span></div><div class="task-aside"><small>${t.due_at?new Date(t.due_at).toLocaleDateString():'NO DUE DATE'}</small><strong>${esc(t.status)}</strong></div>${t.status==='open'&&activeRole==='employee'?`<button class="button-secondary" data-action="complete-task" data-task-id="${t.id}">Complete</button>`:''}</div>`).join('')||'<div class="table-empty">No tasks assigned.</div>';document.querySelectorAll('.task-list').forEach(el=>el.innerHTML=taskHtml);
 if(activeRole==='safety'&&activePage==='Live cameras'){const list=document.querySelector('.site-list');if(list)list.innerHTML=apiCameras.map(c=>`<div class="site-row"><div><div class="site-name">${esc(c.label)}</div><div class="site-meta">${esc(c.site_name)} · ${c.last_seen_at?new Date(c.last_seen_at).toLocaleString():'No signal timestamp'}</div></div><div class="site-status ${c.health==='operational'?'':'warn'}">● ${esc(c.health)}</div><div class="site-score">${c.active?'Active':'Disabled'}</div></div>`).join('')||'<div class="table-empty">No cameras registered for your sites.</div>'}
 if(activeRole==='admin'&&activePage==='Access control'){const rows=[...document.querySelectorAll('.access-row')];apiUsers.forEach((u,i)=>{if(rows[i]){rows[i].querySelector('strong').textContent=u.display_name;rows[i].querySelector('small').textContent=u.email;rows[i].querySelector('.role-chip').textContent=u.role;rows[i].querySelector('.scope-mask').textContent=(u.sites||[]).join(', ')||'No site grants';const b=rows[i].querySelector('[data-action="edit-access"]');if(b){b.dataset.name=u.display_name;b.dataset.userId=u.id}}});rows.slice(apiUsers.length).forEach(r=>r.remove())}
 if(activeRole==='admin'&&activePage==='Audit'&&apiAudit.length){const list=document.querySelector('.event-log');if(list)list.innerHTML=apiAudit.map(a=>`<div class="event-row"><strong>${esc(a.action)}</strong><span>${new Date(a.created_at).toLocaleString()} · ${esc(a.actor)}${a.site_name?' · '+esc(a.site_name):''}</span></div>`).join('')}
 if(activeRole==='safety'&&activePage==='Safety reports'){const list=document.querySelector('.event-log');if(list)list.innerHTML=apiReports.map(r=>`<div class="event-row"><strong>${esc(r.summary)}</strong><span>${esc(r.type)} · ${esc(r.site_name)} · ${esc(r.status)} · ${r.reference||'Report'}</span>${r.status!=='published'?`<button class="text-link" data-publish-report="${r.id}">Review & publish to HQ ↗</button>`:''}</div>`).join('')||'<div class="table-empty">No reports submitted for your sites.</div>'}
 if(activeRole==='hq'&&activePage==='HQ briefings'){const list=document.querySelector('#hqReportList .event-log');if(list)list.innerHTML=apiReports.map(r=>`<div class="event-row"><strong>${esc(r.summary)}</strong><span>${esc(r.type)} · ${esc(r.site_name)} · ${r.reference||'Published report'} · ${new Date(r.published_at).toLocaleDateString()}</span><small>${esc(r.recommendation||'')}</small></div>`).join('')||'<div class="table-empty">No reports have been published yet.</div>'}
 if(activeRole==='hq'&&activePage==='Incident reviews'){const body=document.querySelector('tbody');if(body)body.innerHTML=apiReports.map(r=>`<tr><td class="id-cell">${esc(r.reference||r.id)}</td><td>${esc(r.site_name)}</td><td>${esc(r.event_type||r.type)}</td><td><span class="tag ${(r.severity||'low').toLowerCase()}">${esc(r.severity||r.type)}</span></td><td><span class="tag posted">Published</span></td><td><button class="text-link" data-report-id="${r.id}">Review ↗</button></td></tr>`).join('')||'<tr><td colspan="6" class="table-empty">No published incidents.</td></tr>'}
}
function passwordChangeScreen(){return `<main class="login-screen"><section class="login-card"><a class="brand login-brand" href="#password"><span class="brand-mark">◉</span><span>vision<span class="brand-light">on</span><small>SAFETY INTELLIGENCE</small></span></a><div class="login-eyebrow"><i class="secure-dot"></i> FIRST SIGN-IN SECURITY</div><h1>Create your password.</h1><p class="login-subtitle">Your temporary password has been accepted. Set a personal password to continue.</p><form id="passwordChangeForm" class="login-form"><label for="newPassword">New password</label><div class="login-input-wrap"><input id="newPassword" type="password" autocomplete="new-password" minlength="12" required placeholder="At least 12 characters"><button type="button" class="show-password" data-toggle-password="newPassword">Show</button></div><div class="login-password-label"><label for="confirmPassword">Confirm new password</label></div><div class="login-input-wrap"><input id="confirmPassword" type="password" autocomplete="new-password" minlength="12" required placeholder="Enter it again"><button type="button" class="show-password" data-toggle-password="confirmPassword">Show</button></div><div class="login-password-hint">Use 12 or more characters with uppercase, lowercase, and a number.</div><div class="login-error" id="passwordError" role="alert"></div><button class="login-submit" type="submit">Save password & continue <span>→</span></button></form><div class="login-footer"><span>${esc(currentUser?.email||'')}</span><span>🔒 Encrypted workspace</span></div></section><aside class="login-aside"><div class="login-aside-content"><div class="login-aside-tag"><i class="secure-dot"></i> ACCOUNT SECURITY</div><div class="login-visual"><div class="visual-ring ring-one"></div><div class="visual-ring ring-two"></div><div class="visual-eye">⌑</div></div><div class="login-aside-copy"><span class="section-eyebrow">ONE ACCOUNT. YOUR ACCESS.</span><h2>Your role and site access<br>are set by your admin.</h2><p>Your portal will only display information available to your assigned role.</p></div></div></aside></main>`}
function render(){if(!signedIn){document.querySelector('.sidebar').classList.add('hidden');document.querySelector('.topbar').classList.add('hidden');document.querySelector('.footer').classList.add('hidden');document.getElementById('pageContent').classList.add('login-page-content');document.getElementById('pageContent').innerHTML=needsPasswordChange?passwordChangeScreen():loginScreen();return}document.querySelector('.sidebar').classList.remove('hidden');document.querySelector('.topbar').classList.remove('hidden');document.querySelector('.footer').classList.remove('hidden');document.getElementById('pageContent').classList.remove('login-page-content');renderNav();renderHeader();document.getElementById('pageContent').innerHTML=(liveData?'':`<div class="audit-banner"><strong>PREVIEW NOTICE</strong> &nbsp; Dashboard records are sample content until the portal UI is connected to your database.</div>`)+pageContent();syncLiveDom()}
let toastTimer;function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600)}
function modal(title,description,content,submit='Save'){const wrap=document.createElement('div');wrap.className='modal-backdrop';wrap.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal-header"><div><h2 id="modalTitle">${title}</h2><p>${description}</p></div><button class="modal-close" aria-label="Close">×</button></div>${content}<div class="modal-footer"><button class="button-secondary" data-close>Cancel</button><button class="button-primary" data-submit>${submit}</button></div></section>`;document.body.appendChild(wrap);wrap.addEventListener('click',async e=>{if(e.target===wrap||e.target.closest('[data-close]')||e.target.closest('.modal-close'))wrap.remove();if(e.target.closest('[data-submit]')){const form=wrap.querySelector('form');if(form&&!form.reportValidity())return;try{let msg=wrap.querySelector('[data-success]')?.value||'Saved successfully.';if(liveData&&form?.querySelector('#publishSummary')){const report=apiReports.find(r=>String(r.id)===form.dataset.reportId);const site=apiSites.find(s=>s.name===report?.site_name);if(!site)throw new Error('Report site scope is unavailable.');await apiRequest(`/api/reports/${report.id}/publish`,{method:'POST',body:JSON.stringify({siteId:site.id,summary:form.querySelector('#publishSummary').value,recommendation:form.querySelector('#publishRecommendation').value})});msg='Privacy-screened report published to HQ.'}if(liveData&&form?.querySelector('#reportSummary')){const site=apiSites.find(s=>s.name===form.querySelector('#reportSite').value);if(!site)throw new Error('Select one of your assigned sites.');const kinds={'Incident':'incident','Near miss':'near_miss','Improvement suggestion':'suggestion','Corrective action':'corrective_action'};const report=await apiRequest('/api/reports',{method:'POST',body:JSON.stringify({siteId:site.id,incidentId:form.dataset.incidentId?Number(form.dataset.incidentId):undefined,type:kinds[form.querySelector('#reportType').value],summary:form.querySelector('#reportSummary').value,recommendation:form.querySelector('#reportRecommendation')?.value||''})});msg=`Report ${report.report.id} submitted for manager review.`}if(liveData&&form?.querySelector('#incidentStatus')){const reference=wrap.querySelector('#modalTitle').textContent;const incident=incidents.find(i=>i.id===reference);if(!incident?.dbId)throw new Error('This incident is not linked to a database record.');const statusMap={'Review':'review','Resolved':'resolved','False positive':'false_positive'};await apiRequest(`/api/incidents/${incident.dbId}/review`,{method:'POST',body:JSON.stringify({status:statusMap[form.querySelector('#incidentStatus').value]||form.querySelector('#incidentStatus').value,note:form.querySelector('#incidentNote').value})});if(form.querySelector('#reportToHq').value==='Share privacy-screened summary'){const site=apiSites.find(s=>s.name===incident.site);const summary=form.querySelector('#incidentNote').value||incident.event;const report=await apiRequest('/api/reports',{method:'POST',body:JSON.stringify({siteId:site?.id,incidentId:incident.dbId,type:'incident',summary,recommendation:''})});await apiRequest(`/api/reports/${report.report.id}/publish`,{method:'POST',body:JSON.stringify({siteId:site?.id,summary,recommendation:''})})}msg='Incident review saved.'}if(liveData&&form?.querySelector('#userEmail')){const select=form.querySelector('#userSiteSelect');const siteIds=[...select.selectedOptions].map(o=>apiSites.find(s=>s.name===o.value)?.id).filter(Boolean);const role=form.querySelector('#userRoleSelect').value;const roleMap={'Employee':'employee','Safety Manager':'safety_manager','VP / HQ':'hq','Platform Admin':'platform_admin'};const id=form.dataset.userId;if(id){await apiRequest(`/api/admin/users/${id}/grants`,{method:'PUT',body:JSON.stringify({role:roleMap[role],siteIds})});msg='Access grant updated and audit logged.'}else{const created=await apiRequest('/api/admin/users',{method:'POST',body:JSON.stringify({name:form.querySelector('#userName').value,email:form.querySelector('#userEmail').value,role:roleMap[role],siteIds})});form.dataset.temporaryPassword=created.temporaryPassword;form.dataset.createdEmail=created.user.email;msg='User created and access grant audit logged.'}}const oneTimePassword=form?.dataset.temporaryPassword;const createdEmail=form?.dataset.createdEmail;if(liveData){try{await loadLiveData();render()}catch{}}wrap.remove();if(oneTimePassword){credentialDialog(createdEmail,oneTimePassword);return}toast(msg)}catch(err){toast(err.message)}}});return wrap}
function reportModal(){const available=liveData?apiSites.map(s=>s.name):['North Plant','South Warehouse'];modal('New safety report','Report an incident or propose an improvement for manager review.',`<form class="form-grid"><div class="form-field"><label for="reportType">Report type</label><select id="reportType"><option>Incident</option><option>Near miss</option><option>Improvement suggestion</option><option>Corrective action</option></select></div><div class="form-field"><label for="reportSite">Site</label><select id="reportSite">${available.map(n=>`<option>${esc(n)}</option>`).join('')}</select></div><div class="form-field"><label for="reportCamera">Camera / area (optional)</label><input id="reportCamera" placeholder="e.g. Line 04 · East"></div><div class="form-field"><label for="reportSeverity">Severity</label><select id="reportSeverity"><option>Low</option><option>Medium</option><option>High</option><option>Critical</option></select></div><div class="form-field wide"><label for="reportSummary">What happened or what do you suggest?</label><textarea id="reportSummary" required placeholder="Describe the safety event, contributing conditions, or proposed improvement…"></textarea></div><div class="form-field wide"><label for="reportRecommendation">Recommended action (optional)</label><textarea id="reportRecommendation" placeholder="What should happen next?"></textarea></div><input type="hidden" data-success value="Report saved for manager review."></form>`,'Submit for review')}
function incidentModal(id){const i=incidents.find(x=>x.id===id);if(!i)return;const emp=activeRole==='employee';modal(i.id,emp?'Your linked safety observation':'North Plant · manager review',`<div class="event-log"><div class="event-row"><strong>${esc(i.event)}</strong><span>DETECTED ${esc(i.time)} · ${esc(i.camera)}</span></div><div class="event-row"><strong>${emp?'Personal observation':`Associated account: ${esc(i.person)}`}</strong><span>${emp?'Visible to you and your designated safety team':'Only authorized site safety staff can view identity details.'}</span></div><div class="event-row"><strong>Manager action</strong><span>Confirm observation, document follow-up, or mark as false positive.</span></div></div>${emp?`<form data-incident-ack="${i.dbId||''}"><div class="modal-message">Please confirm you have reviewed this safety observation. Your acknowledgement is visible to your safety team.</div></form>`:`<form class="form-grid" style="margin-top:12px"><div class="form-field"><label for="incidentStatus">Review status</label><select id="incidentStatus"><option>${i.state}</option><option>Review</option><option>Resolved</option><option>False positive</option></select></div><div class="form-field"><label for="reportToHq">Executive sharing</label><select id="reportToHq"><option>Do not share</option><option>Share privacy-screened summary</option></select></div><div class="form-field wide"><label for="incidentNote">Manager note / recommendation</label><textarea id="incidentNote" placeholder="Record verified details, corrective action, or recommendation…"></textarea></div></form>`}`,emp?'Acknowledge':'Save review');const form=document.querySelector('.modal-backdrop form');if(form&&i.dbId)form.dataset.incidentId=i.dbId}
function publishReportModal(id){const report=apiReports.find(r=>String(r.id)===String(id));if(!report)return toast('Report not found.');modal('Review and publish','Check that the summary contains no unnecessary employee identity or sensitive personal details.',`<form class="form-grid" data-report-id="${report.id}"><div class="form-field wide"><label for="publishSummary">Executive summary</label><textarea id="publishSummary" required minlength="5" maxlength="3000">${esc(report.summary)}</textarea></div><div class="form-field wide"><label for="publishRecommendation">Recommendation</label><textarea id="publishRecommendation" maxlength="2000">${esc(report.recommendation||'')}</textarea></div></form>`,'Publish to HQ')}
document.addEventListener('click',async e=>{const logout=e.target.closest('#logoutButton,#profileLogout');if(logout){if(liveData){try{await apiRequest('/api/auth/logout',{method:'POST'})}catch(err){toast("Logout failed. Please retry.");return}}signedIn=false;needsPasswordChange=false;liveData=false;currentUser=null;apiIncidents=[];incidents=sampleIncidents;render();return}const goto=e.target.closest('[data-goto]');if(goto){setPage(goto.dataset.goto);return}const flt=e.target.closest('[data-filter]');if(flt){incidentFilter=flt.dataset.filter;render();return}const inc=e.target.closest('[data-incident]');if(inc){incidentModal(inc.dataset.incident);return}const action=e.target.closest('[data-action]');if(action){switch(action.dataset.action){case'new-report':reportModal();break;case'invite':accessModal();break;case'edit-access':accessModal(action.dataset.name);break;case'assign-task':taskModal();break;case'complete-task':try{if(liveData)await apiRequest(`/api/tasks/${action.dataset.taskId}/complete`,{method:'POST'});toast('Task acknowledgement recorded.');if(liveData){await loadLiveData();render()}else{action.textContent='Done';action.disabled=true}}catch(err){toast(err.message)}break}return}const t=e.target.closest('[data-toast]');if(t)toast(t.dataset.toast)});
document.addEventListener('click',async e=>{const submit=e.target.closest('[data-submit]');const form=submit?.closest('.modal')?.querySelector('form[data-incident-ack]');if(!form||!liveData)return;e.preventDefault();e.stopImmediatePropagation();if(!form.dataset.incidentAck)return toast('Incident record is missing.');try{await apiRequest(`/api/incidents/${form.dataset.incidentAck}/acknowledge`,{method:'POST'});document.querySelector('.modal-backdrop')?.remove();toast('Observation acknowledgement recorded.')}catch(err){toast(err.message)}},{capture:true});
document.addEventListener('click',async e=>{const submit=e.target.closest('[data-submit]');const form=submit?.closest('.modal')?.querySelector('form[data-assign-task]');if(!form||!liveData)return;e.preventDefault();e.stopImmediatePropagation();try{await apiRequest('/api/tasks',{method:'POST',body:JSON.stringify({siteId:Number(form.querySelector('#taskSite').value),employeeId:Number(form.querySelector('#taskEmployee').value),title:form.querySelector('#taskTitle').value,dueAt:form.querySelector('#taskDue').value||null,incidentId:form.querySelector('#taskIncident').value?Number(form.querySelector('#taskIncident').value):null})});await loadLiveData();document.querySelector('.modal-backdrop')?.remove();render();toast('Task assigned and recorded.')}catch(err){toast(err.message)}},{capture:true});
document.addEventListener('click',e=>{const toggle=e.target.closest('#togglePassword,[data-toggle-password]');if(toggle){const input=document.getElementById(toggle.dataset.togglePassword||'loginPassword');if(input){input.type=input.type==='password'?'text':'password';toggle.textContent=input.type==='password'?'Show':'Hide'}return}});
document.addEventListener('click',e=>{const publish=e.target.closest('[data-publish-report]');if(publish){publishReportModal(publish.dataset.publishReport);return}});
document.addEventListener('submit',async e=>{if(e.target.id==='passwordChangeForm'){e.preventDefault();const error=document.getElementById('passwordError');const newPassword=document.getElementById('newPassword').value;const confirmPassword=document.getElementById('confirmPassword').value;if(newPassword!==confirmPassword){error.textContent='The passwords do not match.';return}const submit=e.target.querySelector('[type=submit]');submit.disabled=true;try{await apiRequest('/api/auth/change-password',{method:'POST',body:JSON.stringify({newPassword})});needsPasswordChange=false;signedIn=true;liveData=true;activePage=navForRole()[0][0];await loadLiveData();render()}catch(err){error.textContent=err.message;submit.disabled=false}return}if(e.target.id!=='loginForm')return;e.preventDefault();const error=document.getElementById('loginError');const submit=e.target.querySelector('[type="submit"]');error.textContent='';submit.disabled=true;submit.innerHTML='Signing in… <span>· · ·</span>';try{const response=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({email:document.getElementById('loginEmail').value,password:document.getElementById('loginPassword').value})});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'Sign-in is unavailable.');const roleMap={employee:'employee',safety_manager:'safety',platform_admin:'admin',hq:'hq'};activeRole=roleMap[data.user.role]||'employee';currentUser=data.user;if(data.user.name)roles[activeRole].name=data.user.name;if(data.user.mustChangePassword){needsPasswordChange=true;signedIn=false;render();return}needsPasswordChange=false;liveData=true;signedIn=true;activePage=navForRole()[0][0];try{await loadLiveData()}catch(err){liveData=false;error.textContent=`Signed in, but portal data could not load: ${err.message}`;signedIn=false}render()}catch(err){error.textContent=err.message==='Failed to fetch'?'Sign-in service is unavailable. Please try again later.':err.message;submit.disabled=false;submit.innerHTML='Sign in <span>→</span>'}});
document.addEventListener('input',e=>{if(e.target.id==='incidentSearch'){searchText=e.target.value;const tbody=document.querySelector('tbody');if(tbody)tbody.innerHTML=incidentRows(filteredIncidents())}});
function taskModal(){const siteOpts=apiSites.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('');const seen=new Set();const empOpts=apiEmployees.filter(e=>!seen.has(e.id)&&seen.add(e.id)).map(e=>`<option value="${e.id}">${esc(e.display_name)} · ${esc(e.site_name)}</option>`).join('');modal('Assign a safety task','Assign an action to an employee within a site you manage.',`<form class="form-grid" data-assign-task><div class="form-field"><label for="taskSite">Site</label><select id="taskSite" required>${siteOpts}</select></div><div class="form-field"><label for="taskEmployee">Employee</label><select id="taskEmployee" required>${empOpts}</select></div><div class="form-field wide"><label for="taskTitle">Task</label><input id="taskTitle" required minlength="3" maxlength="250" placeholder="e.g. Complete PPE refresher"></div><div class="form-field"><label for="taskDue">Due date</label><input id="taskDue" type="datetime-local"></div><div class="form-field"><label for="taskIncident">Related incident (optional)</label><select id="taskIncident"><option value="">None</option>${incidents.map(i=>`<option value="${i.dbId||''}">${esc(i.id)} · ${esc(i.event)}</option>`).join('')}</select></div></form>`,'Assign task')}
function credentialDialog(email,password){const wrap=document.createElement('div');wrap.className='modal-backdrop';wrap.innerHTML=`<section class="modal credential-modal" role="dialog" aria-modal="true"><div class="modal-header"><div><h2>Temporary sign-in password</h2><p>Share this with ${esc(email)} through a secure channel. It is shown only once.</p></div></div><div class="credential-value"></div><div class="modal-footer"><button class="button-secondary" data-copy>Copy</button><button class="button-primary" data-close>Done</button></div></section>`;wrap.querySelector('.credential-value').textContent=password;wrap.querySelector('[data-copy]').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(password);toast('Temporary password copied.')}catch{toast('Copy is unavailable; select the password to copy it.')}});wrap.addEventListener('click',e=>{if(e.target===wrap||e.target.closest('[data-close]'))wrap.remove()});document.body.appendChild(wrap)}
function accessModal(name=''){const user=apiUsers.find(u=>u.display_name===name);const roleLabel={employee:'Employee',safety_manager:'Safety Manager',hq:'VP / HQ',platform_admin:'Platform Admin'};const roleOptions=['Employee','Safety Manager','VP / HQ','Platform Admin'].map(x=>`<option ${user&&roleLabel[user.role]===x?'selected':''}>${x}</option>`).join('');const siteOptions=(liveData?apiSites.map(s=>s.name):['North Plant','South Warehouse','East Distribution','West Assembly']).map(x=>`<option ${user?.sites?.includes(x)?'selected':''}>${esc(x)}</option>`).join('');modal(name?'Edit access grant':'Create user access',name?'Adjust role and site scope; changes are written to the access audit.':'Create a user account and assign a role and site. A unique temporary password will be generated.',`<form class="form-grid" ${user?`data-user-id="${user.id}"`:''}>${user?'':`<div class="form-field wide"><label for="userName">Full name</label><input id="userName" required minlength="2" placeholder="Full name"></div>`}<div class="form-field wide"><label for="userEmail">Work email</label><input id="userEmail" type="email" required placeholder="name@company.com" value="${user?esc(user.email):''}" ${user?'readonly':''}></div><div class="form-field"><label for="userRoleSelect">Portal role</label><select id="userRoleSelect">${roleOptions}</select></div><div class="form-field"><label for="userSiteSelect">Site scope (Ctrl/Cmd to select multiple)</label><select id="userSiteSelect" multiple size="4">${siteOptions}</select></div><div class="form-field wide"><span class="site-meta">Admins can manage access only. Safety reports and video remain restricted.</span></div></form>`,name?'Save access':'Create account')}
document.getElementById('menuButton').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));
async function boot(){try{const session=await apiRequest('/api/auth/me');const roleMap={employee:'employee',safety_manager:'safety',platform_admin:'admin',hq:'hq'};currentUser=session.user;activeRole=roleMap[session.user.role]||'employee';if(session.user.name)roles[activeRole].name=session.user.name;if(session.user.mustChangePassword){needsPasswordChange=true}else{liveData=true;signedIn=true;activePage=navForRole()[0][0];await loadLiveData()}}catch{}render()}
boot();
